import { useState, type FormEvent } from 'react';
import {
  JxButton,
  JxInputField,
  JxSelect,
  JxSwitch,
} from '@jinx-ui/react';

export interface ProfileSettings {
  name: string;
  language: string;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  initialValues?: Partial<ProfileSettings>;
  onSave: (settings: ProfileSettings) => void;
}

export default function ProfileSettingsForm({
  initialValues,
  onSave,
}: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialValues?.name ?? '');
  const [language, setLanguage] = useState(initialValues?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(
    initialValues?.emailNotifications ?? false,
  );
  const [nameError, setNameError] = useState('');

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmed = name.trim();
    if (!trimmed) {
      setNameError('Укажите имя');
      return;
    }
    setNameError('');
    onSave({ name: trimmed, language, emailNotifications });
  };

  return (
    <form
      onSubmit={submit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        maxWidth: '420px',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <JxInputField
        label="Имя"
        required
        value={name}
        onChange={(event) => setName(event.target.value)}
        errorText={nameError}
      />

      <JxSelect
        label="Язык интерфейса"
        placeholder="Выберите язык"
        options={[
          { value: 'ru', label: 'Русский' },
          { value: 'en', label: 'English' },
        ]}
        value={language}
        onValueChange={setLanguage}
      />

      <JxSwitch
        label="Уведомления на почту"
        checked={emailNotifications}
        onChange={(event) => setEmailNotifications(event.target.checked)}
      />

      <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
        <JxButton type="submit" variant="primary">
          Сохранить
        </JxButton>
      </div>
    </form>
  );
}

